import { devices, expect, test, type Page } from "@playwright/test"
import { ORGANIZER, PARTICIPANT } from "./support/accounts"
import { openEventList, signIn } from "./support/auth"

test("documents the four main screens and the transport and room lists", async ({ page, browser }, info) => {
  test.setTimeout(120_000)
  const backend = "http://localhost:" + (process.env.E2E_BACKEND_PORT ?? 4190) + "/api"
  const name = "Jana Nováková"
  const event = /Letní kemp 2027(?! – demo)/
  const mobile = info.project.name === "mobile"
  const shot = async (page: Page, key: string) => {
    await page.waitForLoadState("networkidle")
    await page.evaluate(() => document.fonts.ready)
    await page.evaluate(() => window.scrollTo(0, 0))
    const viewport = page.viewportSize()!
    const dims = await page.evaluate(() => [document.documentElement.scrollWidth, document.documentElement.clientWidth, document.documentElement.scrollHeight])
    console.log("VIEW_METRICS", process.env.SHOT_PHASE, key, viewport.width, ...dims)
    await page.screenshot({ path: process.env.SHOT_PATH!.replace(".png", "-" + key + ".png"), fullPage:true, animations:"disabled" })
  }
  await signIn(page,"organizer",ORGANIZER)
  await openEventList(page)
  const eventLink = page.getByRole("link",{name:event})
  await expect(eventLink).toBeVisible()
  const path = (await eventLink.getAttribute("href"))!
  const eventId = path.split("/").at(-1)!
  await shot(page,"events")
  await eventLink.click()
  await expect(page.getByRole("heading",{name:"Occupancy by term"})).toBeVisible()
  await shot(page,"event")
  await page.goto(path+"/applications?q="+encodeURIComponent(name))
  await expect(page.getByText(name,{exact:true}).filter({visible:true})).toBeVisible()
  await page.getByRole("link",{name:/Record payment|Application detail/i}).filter({visible:true}).first().click()
  await expect(page.getByRole("heading",{name:"Status by term"})).toBeVisible()
  await expect(page.getByRole("heading",{name,exact:true})).toBeVisible()
  await shot(page,"application")

  const guest = await browser.newContext({...devices[mobile ? "Pixel 7" : "Desktop Chrome"], viewport:page.viewportSize()!,deviceScaleFactor:1,baseURL:new URL(page.url()).origin,locale:"en-GB",timezoneId:"Europe/Prague"})
  try {
    const other = await guest.newPage()
    await signIn(other,"participant",PARTICIPANT)
    const app = other.getByRole("link",{name:event})
    await expect(app).toBeVisible()
    const appId = (await app.getAttribute("href"))!.split("/").at(-1)!
    const endpoint = backend+"/organizer/events/"+eventId+"/transport"
    const term = async () => {
      const list = await page.request.get(endpoint)
      await expect(list).toBeOK()
      return (await list.json()).terms[0]
    }
    const busName="Praha – letní kemp"
    let first=await term()
    let bus=first.transports.find((item:any)=>item.name===busName)
    if (!bus) {
      await expect(await page.request.post(endpoint,{data:{termId:first.termId,kind:"SCHEDULED",name:busName,departureAt:"2027-07-04T06:00:00.000Z",departurePlace:"Praha, Černý Most"}})).toBeOK()
      bus=(await term()).transports.find((item:any)=>item.name===busName)
    }
    await expect(await other.request.put(backend+"/participant/applications/"+appId+"/transport",{data:{termId:first.termId,transportId:bus.id}})).toBeOK()
    const assign=backend+"/organizer/events/"+eventId+"/terms/"+first.termId+"/room-assignments"
    const response=await page.request.get(assign)
    await expect(response).toBeOK()
    const data=await response.json()
    const isJana=(p:any)=>p.firstName+" "+p.lastName===name
    let room=data.rooms.find((r:any)=>r.participants.some(isJana))
    if (!room) {
      room=data.rooms.find((r:any)=>r.name==="1")
      await expect(await page.request.put(assign+"/"+data.unassigned.find(isJana).applicationTermId,{data:{roomId:room.id,alsoTermIds:[]}})).toBeOK()
    }
    await app.click()
    await expect(other.getByRole("heading",{level:1,name:"Application details"})).toBeVisible()
    await expect(other.getByRole("region",{name:"Terms",exact:true})).toBeVisible()
    await shot(other,"my-application")
    await page.goto(path+"/transport")
    await expect(page.getByText(busName,{exact:true}).filter({visible:true}).first()).toBeVisible()
    await shot(page,"transport")
    await page.goto(path+"/transport/"+bus.id+"/participants")
    await expect(page.getByText(name,{exact:true}).filter({visible:true}).first()).toBeVisible()
    await shot(page,"passengers")
    await page.goto(path+"/rooms")
    await expect(page.getByRole("button",{name:"Edit room "+room.name,exact:true})).toBeVisible()
    const search=page.locator('input[type="search"]').filter({visible:true}).last()
    if (await search.count()) await search.fill(room.name)
    await shot(page,"rooms")
  } finally { await guest.close() }
})
